beta*sum(ES(3:5))/b*mu%num

%% Numerically 
clear all;
Y0 = [1,1,1,1,1];
%sigma=1/5;tau=1/5;theta=1/2;gamma10=1/10;gamma30=1/30;rho=0.2;nu=1;beta=0.5;
b=4;
mu=1/35;
iterMax=100; condOK=1;k=0;
while (k<iterMax & condOK)
    [beta,sigma,gamma10,gamma30,nu,nu2,theta,tau,rho] = random_parameters(true, true);
    Ys = ode45(@(t,Y) ODE_SEIIIS_v4(t,Y,beta,sigma, tau, theta, gamma10,gamma30,nu,rho,mu,b), 1:10000,Y0');
    ES = Ys.y(:,end);
    Rp = (beta*sigma)*((gamma30+mu+nu+rho)*(mu+rho+tau+theta)+tau*theta)./((mu + rho + sigma)*(mu + rho + theta)*(gamma30 + mu + nu + rho)*(gamma10 + mu + rho + tau))
    condOK = ((abs(sum(ES(2:5)))<10^-5) & Rp<1)|((abs(sum(ES(2:5)))>10^-5) & Rp>1);
    k=k+1;
end

%% Solving the utility
clear all; close all;

mu          = 1/30.6; b=10000;
P_VT        = 6.6/100;                            
R_VT        = 1/(1-P_VT); 
rhob        = 1/2.48;      
sigma       = 365/25; 
tau         = 365/46;
theta       = 12/3.6; 
gamma10     = 0;
gamma1      = gamma10+rhob;
gamma30     = 1/20;
gamma3      = gamma30+rhob;
nu          = 0; 
beta        = R_VT/((sigma.*((gamma3+mu+nu).*(mu+rhob+tau+theta)+tau*theta))./((mu+rhob+sigma).*(mu+rhob+theta).*(gamma3+mu+nu).*(gamma1+mu+tau)));
[R0,~,alpha]= Rp_SEIIIS_v4(beta,sigma,tau,nu,gamma10,theta,gamma30,mu,b,0);
% P0          = 1-1/R0;
vecC = linspace(-3,3,1000);
i=0; rhohat=[]; Rrho=[]; Prho=[];
for c=vecC
    i=i+1;
    C_c = @(rho)-U_SEIIIS_mean(rho,c);
    rhohat(i) = fmincon(C_c,0.,[-1;1],[0;alpha]);
    [Rrho(i),~,~]= Rp_SEIIIS_v4(beta,sigma,tau,nu,gamma10,theta,gamma30,mu,b,rhohat(i));
    Prho(i) = 1-1/Rrho(i);
end

figure()
plot(vecC,rhohat)
xlabel('$c$','Interpreter','latex')
ylabel('$\hat\rho$','Interpreter','latex')

tabrecap = [vecC;rhohat;Rrho;Prho]';

tabrecap(tabrecap(:,2)<0.0001,2)=0;
tabrecap(tabrecap(:,4)<0.0001,4)=0;


